import{_ as a,o,c as s,a2 as r}from"./chunks/framework.BQq6mqvm.js";const h=JSON.parse('{"title":"浏览与下载","description":"","frontmatter":{},"headers":[],"relativePath":"usage/files.md","filePath":"usage/files.md","lastUpdated":1790385461000}'),n={name:"usage/files.md"};function e(l,t,i,p,c,g){return o(),s("div",null,[...t[0]||(t[0]=[r('<h1 id="浏览与下载" tabindex="-1">浏览与下载 <a class="header-anchor" href="#浏览与下载" aria-label="Permalink to &quot;浏览与下载&quot;">​</a></h1><h2 id="按人查看文件" tabindex="-1">按人查看文件 <a class="header-anchor" href="#按人查看文件" aria-label="Permalink to &quot;按人查看文件&quot;">​</a></h2><p>左侧菜单的<strong>全部文件</strong>是一个可以展开的分组：</p><ul><li>点它只做一件事：<strong>展开或收起</strong>名下的用户列表（它本身不跳转）。</li><li>展开后列出每个人，<strong>点某个人的名字</strong>就只看他的文件，不必先进列表再筛选。</li><li>名字右侧的**⋯<strong>可以把这个人的目录</strong>置顶**，方便常用的人排在前面。再点一次取消置顶。</li></ul><div class="tip custom-block"><p class="custom-block-title">置顶是记在自己账号上的</p><p>你置顶了谁，只影响你自己看到的顺序；别人看到的还是他自己排的。</p><p>置顶记录存在服务端，换电脑、换浏览器登录后依然生效。</p></div><p>右侧列表显示文件名、大小、上传时间和到期时间；从某个人的名字进来时，列表上方会显示当前在看谁。</p><p><strong>文件夹和文件是同一个列表</strong>（和 Windows 资源管理器一样），文件夹排在文件前面： 文件夹行的「大小」列显示的是它里面有多少项，点这一行就进入该目录。</p><h2 id="搜索文件" tabindex="-1">搜索文件 <a class="header-anchor" href="#搜索文件" aria-label="Permalink to &quot;搜索文件&quot;">​</a></h2><p>在列表上方的搜索框里输入关键词，可以按<strong>文件名</strong>、<strong>上传者姓名</strong>或<strong>工号</strong>搜索； 文件夹按名字单独匹配，所以搜一个目录名也能在结果里看到并进入它。</p><p>搜索会立即生效；点「刷新」可以重新加载列表。</p><h2 id="排序" tabindex="-1">排序 <a class="header-anchor" href="#排序" aria-label="Permalink to &quot;排序&quot;">​</a></h2><p>点击列表表头可以按<strong>文件名</strong>、<strong>大小</strong>、<strong>上传时间</strong>、<strong>到期时间</strong>排序，再点一次切换升序/降序。</p><h2 id="我的文件" tabindex="-1">我的文件 <a class="header-anchor" href="#我的文件" aria-label="Permalink to &quot;我的文件&quot;">​</a></h2><p><strong>我的文件</strong>页面只显示你自己上传的文件，并且<strong>上传入口就在这里</strong>——把文件拖到页面任意位置松手即可，也可以点右上方的<strong>上传文件</strong>按钮，不需要再切换到别的页面。</p><p>只有在这里（以及管理员）才能修改或删除文件，操作列会出现「重命名」和「删除」按钮。</p><h2 id="下载文件" tabindex="-1">下载文件 <a class="header-anchor" href="#下载文件" aria-label="Permalink to &quot;下载文件&quot;">​</a></h2><p>在文件行的操作列点击<strong>下载</strong>，文件会保存到浏览器的默认下载目录。</p><div class="tip custom-block"><p class="custom-block-title">文件名是中文也没问题</p><p>下载下来的文件名会保持原始名称，包括中文、空格与特殊字符。</p></div><h2 id="在线预览" tabindex="-1">在线预览 <a class="header-anchor" href="#在线预览" aria-label="Permalink to &quot;在线预览&quot;">​</a></h2><p>点击<strong>文件名</strong>或操作列的<strong>预览</strong>，会在新标签页打开预览页面，不必先下载。</p><p>支持的文件类型见 <a href="./preview">在线预览</a>。</p><h2 id="重命名文件" tabindex="-1">重命名文件 <a class="header-anchor" href="#重命名文件" aria-label="Permalink to &quot;重命名文件&quot;">​</a></h2><p>在<strong>我的文件</strong>里点击<strong>重命名</strong>，输入新名称后保存。</p><div class="warning custom-block"><p class="custom-block-title">扩展名不能改</p><p>为了保护文件类型策略，<strong>扩展名固定不变</strong>。例如把 <code>报表.xlsx</code> 改成 <code>季度报表</code>，实际会保存为 <code>季度报表.xlsx</code>。</p></div><h2 id="删除文件" tabindex="-1">删除文件 <a class="header-anchor" href="#删除文件" aria-label="Permalink to &quot;删除文件&quot;">​</a></h2><p>点击<strong>删除</strong>并确认后，文件会进入<strong>回收站</strong>。</p><div class="warning custom-block"><p class="custom-block-title">删除后自己就看不到了</p><p>文件进入回收站后，<strong>包括你本人在内的所有普通用户都无法再看到或下载它</strong>，只有管理员能看到并恢复。</p><p>如果需要恢复，请联系管理员，在保留期内（默认 7 天）可以找回。</p></div><h2 id="关于到期时间" tabindex="-1">关于到期时间 <a class="header-anchor" href="#关于到期时间" aria-label="Permalink to &quot;关于到期时间&quot;">​</a></h2><p>每个文件都有到期时间，默认是上传后 15 天。列表里「到期」列的标签会显示剩余天数，临近到期时会变成红色提示。</p><p>到期后文件自动进入回收站。如果需要长期保存重要文件，可以把它<strong>设为永久</strong>（见下一节），或联系管理员调整保留天数。</p><h2 id="设为永久保存" tabindex="-1">设为永久保存 <a class="header-anchor" href="#设为永久保存" aria-label="Permalink to &quot;设为永久保存&quot;">​</a></h2><p>重要文件不想被自动清理时，可以在文件行点<strong>设为永久</strong>。设成永久后，这个文件不会随保留期自动清理，只能手动删除。</p><p>点击后会弹出<strong>二次确认</strong>，框里会告诉你永久空间一共多少、已经用了多少、这次设完还剩多少 —— 永久空间是整个系统<strong>所有人共享</strong>的，总共 <strong>100 GB</strong>（由管理员配置），所以请按需使用。</p><div class="tip custom-block"><p class="custom-block-title">设错了可以改回来</p><p>已设永久的文件，操作列会显示<strong>改回有期限</strong>。点它会按当前的保留天数<strong>重新计算</strong>到期时间（不是恢复成原来的到期时间）。</p></div><div class="warning custom-block"><p class="custom-block-title">永久空间用完了怎么办</p><p>空间不足时无法再设永久，页面会提示还差多少。可以先把一些不再需要的永久文件<strong>删除</strong>（进回收站后就不再占用永久空间），或者联系管理员调大配额。</p></div><h2 id="把整个文件夹设为永久" tabindex="-1">把整个文件夹设为永久 <a class="header-anchor" href="#把整个文件夹设为永久" aria-label="Permalink to &quot;把整个文件夹设为永久&quot;">​</a></h2><p>文件夹那一行的操作列有<strong>有效期</strong>按钮，点它可以把**这个文件夹里的全部文件（含所有子文件夹）**一次设为永久，不用一个个点。</p><p>弹出的确认框同样会说明范围和永久空间情况，并给出两个选择：</p><ul><li><strong>设为永久</strong> —— 整个文件夹里的文件都不再自动清理；</li><li><strong>改回有期限</strong> —— 把它们都改回按保留天数到期。</li></ul><div class="tip custom-block"><p class="custom-block-title">目录本身没有有效期</p><p>有效期是<strong>文件</strong>的属性，文件夹只是一次批量操作的范围。所以设完会告诉你「影响了多少个文件」。</p></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./upload">上传文件</a></li><li><a href="./preview">在线预览</a></li></ul>',42)])])}const u=a(n,[["render",e]]);export{h as __pageData,u as default};
